// runBenchmark 벤치마크 실행
func runBenchmark(name string, code string) *BenchmarkResult {
	result := &BenchmarkResult{
		Name:     name,
		CodeSize: len(code),
	}

	// 메모리 초기화
	var m0 runtime.MemStats
	runtime.ReadMemStats(&m0)

	// 1. 렉싱 (Lexing)
	startLex := time.Now()
	l := lexer.New(code)
	tokenCount := 0
