	Kind     int
	Value    string
	Children []*Node
}

// printBenchmarkResults 벤치마크 결과 출력
func printBenchmarkResults(results []*BenchmarkResult) {
	fmt.Println("\n╔════════════════════════════════════════════════════════════════╗")
