		fmt.Printf("  Large (%d B): %.2f ms (%.1f배 증가)\n", r3.CodeSize, r3.CompileTimeMs, r3.CompileTimeMs/r1.CompileTimeMs)

		// 메모리 사용
		fmt.Println("\n💾 메모리 사용량:")
		fmt.Printf("  Small:  %.3f MB\n", r1.MemoryAllocMB)
