		return NilVal(), err
	}

	return retVal, nil
}

// loadOperand loads a value from an operand
func (vm *VM) loadOperand(op ir.Operand, frame *CallFrame) Value {
	// Immediate integer value
	if op.IsImm {
		return IntVal(op.ImmVal)
