func replMode() {
	fmt.Println("=== FreeLang REPL ===")
	fmt.Println("Enter code (empty line to exit):")

	scanner := bufio.NewScanner(os.Stdin)
	for {
		fmt.Print("fl> ")
		if !scanner.Scan() {
			break
		}

		line := strings.TrimSpace(scanner.Text())
		if line == "" {
			fmt.Println("Exiting REPL.")
			break
		}

		replRunLine(line)
	}
}

