		}
		if found {
			break
		}
	}
	// If not found, use offset 0 as fallback

	// Emit OpFieldLoad instruction
	result := g.newTemp()
	g.emit(Instruction{
		Op:   OpFieldLoad,
		Dest: result,
		Src1: objOp,
		Src2: Operand{IsImm: true, ImmVal: offset},
	})

	return result, nil
}

