// TestStringEquality tests string equality comparison
func TestStringEquality(t *testing.T) {
	_, globals := runProgram(t, "let result = \"abc\" == \"abc\"")

	if resultVal, ok := globals["result"]; !ok || resultVal.Kind != KindBool || !resultVal.BVal {
